import calendar
from datetime import date, timedelta
from itertools import islice

_WEEKDAYS = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}


def _month_at(s: date, offset: int):
    idx = s.year * 12 + (s.month - 1) + offset
    y, m = divmod(idx, 12)
    return y, m + 1


def _gen_daily(s: date, k: int):
    d = s
    step = timedelta(days=k)
    while True:
        yield d
        d += step


def _gen_weekly(s: date, k: int, days: list):
    monday = s - timedelta(days=s.weekday())
    w = 0
    while True:
        base = monday + timedelta(weeks=w * k)
        for wd in days:
            d = base + timedelta(days=wd)
            if d >= s:
                yield d
        w += 1


def _gen_monthly_day(s: date, k: int, day: int):
    m = 0
    while True:
        y, mo = _month_at(s, m * k)
        n = calendar.monthrange(y, mo)[1]
        if day == -1:
            dd = n
        elif day <= n:
            dd = day
        else:
            dd = None
        if dd is not None:
            d = date(y, mo, dd)
            if d >= s:
                yield d
        m += 1


def _gen_monthly_nth(s: date, k: int, nth: int, wd: int):
    m = 0
    while True:
        y, mo = _month_at(s, m * k)
        n = calendar.monthrange(y, mo)[1]
        if nth > 0:
            first_wd = date(y, mo, 1).weekday()
            dd = 1 + (wd - first_wd) % 7 + 7 * (nth - 1)
            valid = dd <= n
        else:
            last = date(y, mo, n)
            dd = n - (last.weekday() - wd) % 7
            valid = True
        if valid:
            d = date(y, mo, dd)
            if d >= s:
                yield d
        m += 1


def _gen_yearly(s: date, k: int, mm: int, dd: int):
    j = 0
    while True:
        y = s.year + j * k
        try:
            d = date(y, mm, dd)
        except ValueError:
            d = None
        if d is not None and d >= s:
            yield d
        j += 1


def recur(start: str, rule: str, count: int) -> list[str]:
    s = date.fromisoformat(start)
    parts = rule.split()
    kind = parts[0]

    if kind == "DAILY":
        gen = _gen_daily(s, int(parts[1]))
    elif kind == "WEEKLY":
        k = int(parts[1])
        days = sorted(_WEEKDAYS[t] for t in parts[2].split(","))
        gen = _gen_weekly(s, k, days)
    elif kind == "MONTHLY":
        k = int(parts[1])
        if len(parts) == 3:
            gen = _gen_monthly_day(s, k, int(parts[2]))
        else:
            gen = _gen_monthly_nth(s, k, int(parts[2]), _WEEKDAYS[parts[3]])
    elif kind == "YEARLY":
        k = int(parts[1])
        mm, dd = (int(x) for x in parts[2].split("-"))
        gen = _gen_yearly(s, k, mm, dd)
    else:
        raise ValueError(f"Unknown rule: {rule}")

    return [d.isoformat() for d in islice(gen, count)]
